const DEFAULT_IDLE_TIMEOUT_MS = 60000;
const DEFAULT_REPLAY_INTERVAL_MS = 8000;
const DEFAULT_MAX_TOTAL_COUNT = 300;

/**
 * Keeps the tree visibly growing during quiet stretches of a live event: once
 * `idleTimeoutMs` passes with no real activity (`notifyActivity()` not
 * called), it starts re-adding already-seen messages on a loop so the canopy
 * keeps filling in instead of sitting static. Stops automatically once the
 * total message count reaches `maxTotalCount`, so an all-day unattended
 * display doesn't accumulate an unbounded number of sticky DOM elements.
 *
 * Mirrors js/csvPoller.js's start/stop-via-plain-timers pattern so it can be
 * tested the same way, with `t.mock.timers`.
 */
export function createIdleReplay({
  getMessages,
  getCurrentCount,
  onReplay,
  idleTimeoutMs = DEFAULT_IDLE_TIMEOUT_MS,
  replayIntervalMs = DEFAULT_REPLAY_INTERVAL_MS,
  maxTotalCount = DEFAULT_MAX_TOTAL_COUNT,
}) {
  let idleTimer = null;
  let replayTimer = null;
  let cursor = 0;
  let replaySeq = 0;

  function stopReplaying() {
    if (replayTimer !== null) {
      clearInterval(replayTimer);
      replayTimer = null;
    }
  }

  function replayNext() {
    if (getCurrentCount() >= maxTotalCount) {
      stopReplaying();
      return;
    }
    const messages = getMessages();
    if (messages.length === 0) {
      stopReplaying();
      return;
    }
    const source = messages[cursor % messages.length];
    cursor += 1;
    replaySeq += 1;
    onReplay({
      id: `${source.id}::replay:${replaySeq}`,
      center: source.center,
      message: source.message,
    });
  }

  function startReplaying() {
    if (replayTimer !== null) return;
    if (getMessages().length === 0) return;
    if (getCurrentCount() >= maxTotalCount) return;
    // Fire the first replay immediately (right as we go idle) instead of
    // waiting a full replayIntervalMs on top of the idle timeout.
    replayTimer = setInterval(replayNext, replayIntervalMs);
    replayNext();
  }

  function notifyActivity() {
    stopReplaying();
    if (idleTimer !== null) {
      clearTimeout(idleTimer);
    }
    idleTimer = setTimeout(startReplaying, idleTimeoutMs);
  }

  function stop() {
    if (idleTimer !== null) {
      clearTimeout(idleTimer);
      idleTimer = null;
    }
    stopReplaying();
  }

  return { notifyActivity, stop };
}
