/**
 * Keeps sticky (leaf/flower) elements at the same *physical* size relative to
 * the tree artwork regardless of viewport size, instead of a fixed CSS px
 * that used to drift off-scale as `.tree-frame` grew or shrank.
 *
 * `.tree-frame` is locked to the artwork's native 1672x940 aspect ratio, so a
 * single width ratio (current rendered width / native width) tells us how
 * much to scale a sticky authored at `BASE_STICKY_WIDTH_PX` (the local
 * coordinate space width its clip-path shapes in css/style.css are drawn
 * in; each shape's own height is baked into its path, see
 * js/stickyVisuals.js).
 */
export const NATIVE_FRAME_WIDTH = 1672;
export const NATIVE_FRAME_HEIGHT = 940;
export const BASE_STICKY_WIDTH_PX = 40;

export function computeFrameScale(frameWidthPx, nativeFrameWidth = NATIVE_FRAME_WIDTH) {
  if (!Number.isFinite(frameWidthPx) || frameWidthPx <= 0) {
    return 1;
  }
  return frameWidthPx / nativeFrameWidth;
}

/** Every leaf is drawn this much larger than its authored size (Mishima 2026-10-20). */
export const LEAF_SIZE_BOOST = 1.1;
/** Up to this many messages every leaf keeps its full size. */
export const FULL_SIZE_MAX_COUNT = 400;
/** Smallest leaf size (fraction of full) however many messages arrive. */
export const MIN_COUNT_SCALE = 0.6;

/**
 * Shrinks every leaf together once the tree holds more than
 * FULL_SIZE_MAX_COUNT messages, so the canopy keeps roughly the same total
 * leaf area instead of burying the tree (scale ~ sqrt(limit / count)),
 * all on top of LEAF_SIZE_BOOST.
 */
export function computeCountScale(count) {
  if (!(count > FULL_SIZE_MAX_COUNT)) {
    return LEAF_SIZE_BOOST;
  }
  return LEAF_SIZE_BOOST * Math.max(MIN_COUNT_SCALE, Math.sqrt(FULL_SIZE_MAX_COUNT / count));
}

/**
 * Past this many messages per-leaf sway/glow are switched off to keep the
 * display smooth. Kept separate from FULL_SIZE_MAX_COUNT: at 400 swaying
 * leaves the display already dropped to ~40fps (measured 2026-10-20).
 */
export const DENSE_MIN_COUNT = 300;

export function isDenseCount(count) {
  return count > DENSE_MIN_COUNT;
}
