/**
 * Deterministic anchor-slot assignment for sticky notes.
 *
 * Rule (spec: "最寄りのアンカーポイント付近へ移動して定着"): the Nth message
 * ever added claims the Nth-nearest-to-reference anchor while anchors remain
 * unclaimed. Once all anchors have one occupant, assignment wraps back to the
 * nearest anchor first (index 0 of the sorted order) and keeps cycling,
 * giving every anchor a second occupant before any gets a third, and so on.
 */

import { NATIVE_FRAME_WIDTH, NATIVE_FRAME_HEIGHT } from "./leafScale.js";

function distance(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.sqrt(dx * dx + dy * dy);
}

/** Returns anchor indices ordered nearest-to-farthest from referencePoint. */
export function sortAnchorsByDistance(anchors, referencePoint) {
  return anchors
    .map((anchor, index) => ({ index, d: distance(anchor, referencePoint) }))
    .sort((a, b) => a.d - b.d)
    .map((entry) => entry.index);
}

/**
 * orderIndex: 0-based position of this message among all messages ever
 * assigned an anchor (stable arrival order).
 * sortedAnchorIndices: fixed nearest->farthest anchor index order.
 */
export function computeAnchorAssignment(orderIndex, sortedAnchorIndices) {
  const anchorCount = sortedAnchorIndices.length;
  const slot = orderIndex % anchorCount;
  const occupantIndex = Math.floor(orderIndex / anchorCount);
  return { anchorIndex: sortedAnchorIndices[slot], occupantIndex };
}

/**
 * Radius (native artwork px) of the disk that overflow stickies scatter in
 * around their shared anchor. Bounded so even ~2000 messages stay on the
 * canopy instead of spilling into the sky (the old sqrt(occupantIndex)
 * spiral grew without limit).
 */
export const SCATTER_RADIUS_PX = 75;

/**
 * Offset (in the same % coordinate space as anchors) for the occupantIndex-th
 * sticky settled at a shared anchor. Overflow stickies land at an
 * area-uniform point (r = R * sqrt(u), theta = 2 * PI * v) in a fixed disk,
 * where {u, v} come from the message id (stickyVisuals getStickyScatter), so
 * a sticky never moves when later messages arrive. The disk is measured in
 * px and converted per axis so it stays round on the non-square frame.
 */
export function computeStickyOffset(occupantIndex, { u, v }) {
  if (occupantIndex === 0) {
    return { dx: 0, dy: 0 };
  }
  const radiusPx = SCATTER_RADIUS_PX * Math.sqrt(u);
  const angle = 2 * Math.PI * v;
  return {
    dx: ((radiusPx * Math.cos(angle)) / NATIVE_FRAME_WIDTH) * 100,
    dy: ((radiusPx * Math.sin(angle)) / NATIVE_FRAME_HEIGHT) * 100,
  };
}
