import { parseCsv, csvRowsToRecords } from "./csvParser.js";

const SHEET_ID_PATTERN = /\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/;
const GID_PATTERN = /[?#&]gid=([0-9]+)/;
const DEFAULT_INTERVAL_MS = 30000;
const DEFAULT_MAX_START_JITTER_MS = 3000;

/**
 * This app only ever reads columns C (学習センター) and D (message) — never
 * A (timestamp) or B (email, PII) — so every url this returns is pinned to
 * `range=C:D`, overriding whatever range (if any) the input already had.
 *
 * This only stops *this app's own request* from asking for more columns;
 * it is NOT a substitute for keeping the source response sheet itself
 * non-public. If the sheet is shared "anyone with the link can view" so
 * this poller can reach it unauthenticated, anyone with that same link can
 * open it directly (or just drop the range param) and see every column,
 * emails included. The sheet entered here should be a C/D-only public view
 * (e.g. a separate published sheet/tab), never the raw response sheet.
 */
export function toCsvUrl(input) {
  if (!input) return null;
  if (/output=csv|gviz\/tq/.test(input)) return withForcedColumnRange(input);
  const match = SHEET_ID_PATTERN.exec(input);
  if (!match) return null;
  const gidMatch = GID_PATTERN.exec(input);
  const gid = gidMatch ? gidMatch[1] : "0";
  return withForcedColumnRange(`https://docs.google.com/spreadsheets/d/${match[1]}/gviz/tq?tqx=out:csv&gid=${gid}`);
}

function withForcedColumnRange(url) {
  const withoutRange = url.replace(/[?&]range=[^&]*/, "");
  const separator = withoutRange.includes("?") ? "&" : "?";
  return `${withoutRange}${separator}range=C:D`;
}

async function fetchCsvRows(csvUrl, fetchImpl) {
  const res = await fetchImpl(csvUrl);
  if (!res.ok) throw new Error(`bad status: ${res.status}`);
  return parseCsv(await res.text());
}

/**
 * Polls a Google Sheets CSV export on an interval and reports every record
 * currently in the sheet on each successful poll. Dedup is the caller's
 * responsibility (messageStore.addMessage already ignores known ids), so
 * this module can stay a dumb "fetch, parse, hand rows over" loop.
 *
 * Design notes carried over from the growth-tree-message sibling project:
 * - start()/stop() are idempotent; start() ignores a second call while
 *   already running (including while the initial jitter delay is pending).
 * - stop() bumps a generation counter and clears any pending timers so a
 *   fetch already in flight cannot deliver stale data after stop().
 * - The very first poll is delayed by a random 0..maxStartJitterMs so that
 *   multiple signage screens polling the same sheet don't all hit it at once.
 */
export function createCsvPoller({
  getUrl,
  onNewRecords,
  onStatusChange,
  intervalMs = DEFAULT_INTERVAL_MS,
  maxStartJitterMs = DEFAULT_MAX_START_JITTER_MS,
  fetchImpl = fetch,
  // (sheetInput) -> Promise<string[][]>. Defaults to fetch + csv; main.js
  // injects the gviz JSONP loader (js/gvizJsonp.js) so file:// works.
  loadRows = (sheetInput) => fetchCsvRows(toCsvUrl(sheetInput), fetchImpl),
  randomImpl = Math.random,
}) {
  let intervalId = null;
  let jitterTimeoutId = null;
  let generation = 0;

  async function pollOnce() {
    const myGeneration = generation;
    const sheetInput = getUrl();
    if (!toCsvUrl(sheetInput)) {
      onStatusChange?.({ online: false });
      return;
    }
    try {
      const rows = await loadRows(sheetInput);
      if (myGeneration !== generation) return;
      const records = csvRowsToRecords(rows);
      onStatusChange?.({ online: true });
      onNewRecords(records);
    } catch {
      if (myGeneration !== generation) return;
      onStatusChange?.({ online: false });
    }
  }

  function start() {
    if (intervalId !== null || jitterTimeoutId !== null) return;
    const delay = randomImpl() * maxStartJitterMs;
    jitterTimeoutId = setTimeout(() => {
      jitterTimeoutId = null;
      pollOnce();
      intervalId = setInterval(pollOnce, intervalMs);
    }, delay);
  }

  function stop() {
    generation += 1;
    if (jitterTimeoutId !== null) {
      clearTimeout(jitterTimeoutId);
      jitterTimeoutId = null;
    }
    if (intervalId !== null) {
      clearInterval(intervalId);
      intervalId = null;
    }
  }

  return { start, stop };
}
