/**
 * Deterministic per-message kind/variant/depth/color/opacity/size/rotation/
 * jitter/sway, so a sticky always looks the same across polls/reloads
 * without storing anything beyond the message id. Shapes are rendered as
 * leaf/flower silhouettes in css/style.css.
 *
 * Sizing/variety follows Mishima's canopy spec (2026-09-08 revision,
 * reviewed with GPT-5.5): a leaf's on-screen width is decided directly by a
 * single `depth` roll (background/midground/foreground) rather than
 * multiplying an independent size-tier by a separate perspective multiplier
 * — multiplying the two produced widths outside the documented range (see
 * DEPTH_WIDTH_RANGES below). Each leaf variant's height is baked into its
 * own clip-path in css/style.css rather than tracked as a separate number
 * here, so a uniform
 * width-based scale (js/leafScale.js) always keeps the right aspect ratio.
 *
 * Color tone / depth opacity / wind sway follow a second 2026-09-08 review
 * (same day, later pass) with GPT-5.5, requested by Mishima to make the
 * canopy read as less uniform: each center's hue stays fixed (identity is
 * still the priority), but leaves vary in brightness/saturation, fade
 * slightly by depth, and a minority sway in the wind.
 */
export const STICKY_KINDS = ["leaf", "flower"];
export const LEAF_VARIANTS = ["oval-a", "oval-b", "heart"];

/** Leaves dominate a real canopy; flowers are an occasional accent. */
const FLOWER_PROBABILITY = 0.15;

/** Fallback palette for a message whose center (column C) is missing/unrecognized. */
export const LEAF_COLORS = ["#4FAE62", "#D95B45", "#E3C43F", "#3E9BB5", "#9B68D0"];
/**
 * Pale cream/coral, deliberately far from LEAF_COLORS' saturated hues (and
 * especially from 千葉's violet) so kind alone is never ambiguous with
 * center color at a glance.
 */
export const FLOWER_COLORS = ["#FFF1D6", "#FFD7C8", "#F7E7F0", "#FFE4A8"];

/**
 * 第19回勇志祭's 5 venues (福岡・熊本・宮崎・大分・千葉), reviewed with
 * GPT-5.5 (2026-09-08 revision): Mishima's first pass kept all 5 within one
 * green family for a unified canopy, but that made venues indistinguishable
 * except up close. These spread the hue wheel instead (green/red/yellow/
 * blue/violet) so a venue reads at a glance from across the room, avoiding
 * the darkest blue-violets (get lost against the upper sky), orange/gold
 * (blends into the horizon), and deep crimson (too close to the sunset's
 * own red-orange). Aliases absorb the punctuation/suffix variants a Google
 * Form's own option text might use ("福岡学習センター" vs "福岡センター" vs
 * bare "福岡"); an unrecognized or blank center falls back to LEAF_COLORS
 * (see getStickyLeafBaseColor) rather than breaking.
 *
 * 熊本/千葉 revised again same day, after Mishima flagged them blending into
 * the sky (熊本's red-orange near --horizon-gold, 千葉's violet near
 * --sky-violet): 熊本 moved toward crimson/raspberry (away from orange),
 * 千葉 brightened and shifted blue-violet (away from the sky's own violet
 * and further from 大分's blue). Picked from a GPT-5.5-reviewed shortlist,
 * confirmed with Mishima before applying.
 */
const CENTER_COLOR_ALIASES = {
  福岡: "#4FAE62",
  福岡学習センター: "#4FAE62",
  福岡センター: "#4FAE62",
  熊本: "#F04F69",
  熊本学習センター: "#F04F69",
  熊本センター: "#F04F69",
  宮崎: "#E3C43F",
  宮崎学習センター: "#E3C43F",
  宮崎センター: "#E3C43F",
  大分: "#3E9BB5",
  大分学習センター: "#3E9BB5",
  大分センター: "#3E9BB5",
  千葉: "#9D7AF5",
  千葉学習センター: "#9D7AF5",
  千葉センター: "#9D7AF5",
};

export const STICKY_DEPTHS = ["background", "midground", "foreground"];

const DEPTH_WEIGHTS = { background: 0.2, midground: 0.6, foreground: 0.2 };
/**
 * Bumped ~2 size-steps larger than the original spec per Mishima's
 * 2026-09-08 follow-up (each range x~1.4, rounded), after the hue-spread
 * palette made individual leaves easier to pick out and worth seeing bigger.
 */
const DEPTH_WIDTH_RANGES = {
  background: { min: 14, max: 25 },
  midground: { min: 28, max: 39 },
  foreground: { min: 34, max: 45 },
};

export const LEAF_WIDTH_MIN_PX = Math.min(...Object.values(DEPTH_WIDTH_RANGES).map((r) => r.min));
export const LEAF_WIDTH_MAX_PX = Math.max(...Object.values(DEPTH_WIDTH_RANGES).map((r) => r.max));

/**
 * Most leaves keep a natural, still-attached-looking tilt; a minority land
 * dramatically askew (near upside-down or sideways) so a canopy of hundreds
 * of leaves doesn't all read as "the same orientation" (Mishima, 2026-09-09
 * - the old +/-30deg-only cap kept every leaf's serrated tip pointing
 * roughly up). Full 0-360deg was considered (GPT-5.5 design review) and
 * rejected: it reads as confetti/fallen leaves rather than ones still on
 * the tree.
 */
export const LEAF_ROTATION_NATURAL_MAX_DEG = 70;
export const LEAF_ROTATION_DRAMATIC_MIN_DEG = 110;
export const LEAF_ROTATION_DRAMATIC_MAX_DEG = 250;
const LEAF_ROTATION_DRAMATIC_PROBABILITY = 0.2;

/**
 * Small per-leaf position nudge (native 1672x940 px), so leaves don't sit
 * pixel-perfect on their anchor. Kept well below the ~53px golden-angle
 * spiral offset that already spreads repeat occupants at a shared anchor
 * (js/anchorPlacement.js), so it reads as organic variation rather than
 * fighting that layout.
 */
export const LEAF_JITTER_MIN_PX = 2;
export const LEAF_JITTER_MAX_PX = 6;

/** Max probability (at the sunset-side edge) that a leaf gets the warm accent palette. */
const FOREGROUND_ACCENT_MAX_X_PROBABILITY = 0.5;
/** Extra accent probability for foreground-depth leaves, on top of the x-position term. */
const FOREGROUND_ACCENT_DEPTH_BONUS = 0.15;

/**
 * Small brightness/saturation-only variants layered on a center's fixed hue
 * (GPT-5.5, 2026-09-08): keeps every leaf recognizably "that center's color"
 * while avoiding an all-leaves-identical look. Hue is never touched.
 *
 * The "shade" floor was raised from 0.94 to 0.97 the same day, after the
 * 熊本/千葉 contrast fix: a dark variant combined with background-depth
 * opacity was sinking those colors back toward the sky, undoing the fix for
 * some leaves. Raised for all 5 centers rather than only 熊本/千葉, so the
 * tone rule stays one shared constant instead of a center-specific carve-out.
 */
const TONE_VARIANTS = [
  { lightnessMultiplier: 0.97, saturationMultiplier: 1.03 },
  { lightnessMultiplier: 1.0, saturationMultiplier: 1.0 },
  { lightnessMultiplier: 1.07, saturationMultiplier: 0.96 },
];

/**
 * Fixed, depth-driven opacity (GPT-5.5, 2026-09-08): background leaves fade
 * slightly so the canopy reads with more depth, without muddying color
 * legibility. Deliberately not randomized per-leaf, so the depth ordering
 * stays readable.
 */
const DEPTH_OPACITY = {
  background: 0.82,
  midground: 0.92,
  foreground: 1,
};

/** Fraction of leaves that sway in the wind; the rest stay still (perf + naturalism with hundreds of leaves on screen, GPT-5.5 2026-09-08). */
const SWAY_PROBABILITY = 0.3;
/** A handful of period lengths rather than a continuous roll, so phases stay easy to reason about while still reading as organic once spread out via getStickySwayDelay. */
const SWAY_PERIODS_SEC = [7, 9, 11];
const SWAY_AMPLITUDE_RANGES = {
  background: { min: 1, max: 1.6 },
  midground: { min: 1.6, max: 2.2 },
  foreground: { min: 2.2, max: 3 },
};

function hexToHsl(hex) {
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  if (max === min) return { h: 0, s: 0, l };
  const d = max - min;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  let h;
  if (max === r) h = (g - b) / d + (g < b ? 6 : 0);
  else if (max === g) h = (b - r) / d + 2;
  else h = (r - g) / d + 4;
  return { h: h * 60, s, l };
}

function hslToHex({ h, s, l }) {
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  const [r0, g0, b0] =
    h < 60 ? [c, x, 0] : h < 120 ? [x, c, 0] : h < 180 ? [0, c, x] : h < 240 ? [0, x, c] : h < 300 ? [x, 0, c] : [c, 0, x];
  const toHex = (v) =>
    Math.round(Math.max(0, Math.min(1, v + m)) * 255)
      .toString(16)
      .padStart(2, "0");
  return `#${toHex(r0)}${toHex(g0)}${toHex(b0)}`;
}

function applyTone(hex, tone) {
  const { h, s, l } = hexToHsl(hex);
  const toned = {
    h,
    s: Math.max(0, Math.min(1, s * tone.saturationMultiplier)),
    l: Math.max(0, Math.min(1, l * tone.lightnessMultiplier)),
  };
  return hslToHex(toned);
}

function pickToneVariant(id) {
  const roll = hashToFraction(`tone:${id}`);
  const index = Math.min(Math.floor(roll * TONE_VARIANTS.length), TONE_VARIANTS.length - 1);
  return TONE_VARIANTS[index];
}

function hashStringToInt(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i += 1) {
    hash = (hash * 31 + str.charCodeAt(i)) | 0;
  }
  // Finalizer (murmur3-style avalanche). Real message ids are all
  // "row_<sequential number>", differing only in that numeric suffix; the
  // raw multiplicative hash above mixes those poorly for some seed
  // prefixes (e.g. "kind:row_0".."kind:row_59" all landed on the same side
  // of the flower-probability threshold), which this spreads out evenly.
  hash ^= hash >>> 16;
  hash = Math.imul(hash, 0x85ebca6b);
  hash ^= hash >>> 13;
  hash = Math.imul(hash, 0xc2b2ae35);
  hash ^= hash >>> 16;
  return Math.abs(hash);
}

function hashToFraction(seed) {
  return (hashStringToInt(seed) % 1000) / 1000;
}

/** Full-width spaces (common in Japanese form input) count as trimmable whitespace too. */
function normalizeCenterName(center) {
  return String(center ?? "")
    .replace(/[　\s]+/gu, "")
    .trim();
}

export function getStickyKind(id) {
  return hashToFraction(`kind:${id}`) < FLOWER_PROBABILITY ? "flower" : "leaf";
}

export function getStickyVariant(id) {
  if (getStickyKind(id) === "flower") {
    return "flower";
  }
  const roll = hashToFraction(`variant:${id}`);
  const index = Math.min(Math.floor(roll * LEAF_VARIANTS.length), LEAF_VARIANTS.length - 1);
  return LEAF_VARIANTS[index];
}

export function getStickyDepth(id) {
  const roll = hashToFraction(`depth:${id}`);
  let cumulative = 0;
  for (const depth of STICKY_DEPTHS) {
    cumulative += DEPTH_WEIGHTS[depth];
    if (roll < cumulative) {
      return depth;
    }
  }
  return STICKY_DEPTHS[STICKY_DEPTHS.length - 1];
}

export function getStickyLeafWidth(id) {
  const range = DEPTH_WIDTH_RANGES[getStickyDepth(id)];
  const widthRoll = hashToFraction(`width:${id}`);
  return range.min + widthRoll * (range.max - range.min);
}

export function getStickyRotation(id) {
  const roll = hashToFraction(`rotation:${id}`);
  if (hashToFraction(`rotation-bucket:${id}`) < LEAF_ROTATION_DRAMATIC_PROBABILITY) {
    return (
      LEAF_ROTATION_DRAMATIC_MIN_DEG + roll * (LEAF_ROTATION_DRAMATIC_MAX_DEG - LEAF_ROTATION_DRAMATIC_MIN_DEG)
    );
  }
  return -LEAF_ROTATION_NATURAL_MAX_DEG + roll * (2 * LEAF_ROTATION_NATURAL_MAX_DEG);
}

/**
 * Deterministic {u, v} in [0, 1) that picks where an overflow sticky lands in
 * its anchor's scatter disk. `attempt` > 0 gives a fresh spot for the same
 * message when an earlier one fell on the trunk (js/messageStore.js).
 */
export function getStickyScatter(id, attempt = 0) {
  const suffix = attempt === 0 ? "" : `#${attempt}`;
  return { u: hashToFraction(`scatter-radius:${id}${suffix}`), v: hashToFraction(`scatter-angle:${id}${suffix}`) };
}

/** Returns a small, deterministic {dxPx, dyPx} nudge in native artwork px. */
export function getStickyJitter(id) {
  const angle = hashToFraction(`jitter-angle:${id}`) * 2 * Math.PI;
  const radius = LEAF_JITTER_MIN_PX + hashToFraction(`jitter-radius:${id}`) * (LEAF_JITTER_MAX_PX - LEAF_JITTER_MIN_PX);
  return { dxPx: radius * Math.cos(angle), dyPx: radius * Math.sin(angle) };
}

/**
 * The sunset sits on the right side of the canopy artwork, so leaves further
 * right are more likely to catch its light. Foreground leaves get a small
 * extra bump, independent of where they land, since a nearer leaf is more
 * likely to catch direct light regardless of side.
 */
export function getStickyForegroundAccent(id, anchorXPercent) {
  const xFraction = Math.max(0, Math.min(1, anchorXPercent / 100));
  const depthBonus = getStickyDepth(id) === "foreground" ? FOREGROUND_ACCENT_DEPTH_BONUS : 0;
  const probability = xFraction * FOREGROUND_ACCENT_MAX_X_PROBABILITY + depthBonus;
  return hashToFraction(`accent:${id}`) < probability;
}

/**
 * The venue color (column C), before any sunset warming is applied. Carries
 * a small per-leaf tone variant (brightness/saturation only, hue untouched)
 * so same-center leaves aren't all bit-for-bit identical.
 */
export function getStickyLeafBaseColor(id, center) {
  const normalized = normalizeCenterName(center);
  const known = CENTER_COLOR_ALIASES[normalized];
  // Missing/unrecognized center (blank cell, typo, a venue added after this
  // list was written): still needs *a* stable color rather than breaking.
  const base = known ?? LEAF_COLORS[hashStringToInt(`color:${id}`) % LEAF_COLORS.length];
  return applyTone(base, pickToneVariant(id));
}

/** Fixed opacity for a leaf's own depth (see DEPTH_OPACITY); never randomized per-leaf. */
export function getStickyOpacity(id) {
  return DEPTH_OPACITY[getStickyDepth(id)];
}

/** Whether this leaf sways in the wind (a minority do; see SWAY_PROBABILITY). */
export function getStickySwayEnabled(id) {
  return hashToFraction(`sway:${id}`) < SWAY_PROBABILITY;
}

/** One of a handful of period lengths (SWAY_PERIODS_SEC), in seconds. */
export function getStickySwayPeriod(id) {
  const roll = hashToFraction(`sway-period:${id}`);
  const index = Math.min(Math.floor(roll * SWAY_PERIODS_SEC.length), SWAY_PERIODS_SEC.length - 1);
  return SWAY_PERIODS_SEC[index];
}

/** Sway amplitude in degrees, scaled by depth so foreground leaves sway more visibly than background ones. */
export function getStickySwayAngle(id) {
  const range = SWAY_AMPLITUDE_RANGES[getStickyDepth(id)];
  const roll = hashToFraction(`sway-angle:${id}`);
  return range.min + roll * (range.max - range.min);
}

/** A negative delay (as a fraction of this leaf's own period) so swaying leaves don't all start in sync. */
export function getStickySwayDelay(id) {
  const period = getStickySwayPeriod(id);
  const phase = hashToFraction(`sway-phase:${id}`);
  return -(phase * period);
}

/**
 * The venue color is never altered by lighting — GPT-5.5's review flagged
 * that blending 5 hue-spread colors toward one gold target erodes the very
 * distinctness this palette exists for. The sunset effect instead lives in
 * CSS (see .sticky[data-sunlit] / .card.settling[data-sunlit] in
 * css/style.css): a brightness lift plus a warm drop-shadow glow, driven by
 * the `sunlit` flag from resolveStickyVisual, layered on top of this exact
 * color rather than shifting its hue.
 */
export function getStickyColor(id, center = null) {
  if (getStickyKind(id) === "flower") {
    return FLOWER_COLORS[hashStringToInt(`color:${id}`) % FLOWER_COLORS.length];
  }
  return getStickyLeafBaseColor(id, center);
}

/** Single entry point combining every visual decision for one message id. */
export function resolveStickyVisual(id, anchor, center = null) {
  const anchorXPercent = anchor?.x ?? 50;
  const swayEnabled = getStickySwayEnabled(id);
  return {
    kind: getStickyKind(id),
    variant: getStickyVariant(id),
    depth: getStickyDepth(id),
    width: getStickyLeafWidth(id),
    color: getStickyColor(id, center),
    opacity: getStickyOpacity(id),
    sunlit: getStickyForegroundAccent(id, anchorXPercent),
    rotation: getStickyRotation(id),
    jitter: getStickyJitter(id),
    swayEnabled,
    swayAngle: swayEnabled ? getStickySwayAngle(id) : 0,
    swayPeriod: swayEnabled ? getStickySwayPeriod(id) : 0,
    swayDelay: swayEnabled ? getStickySwayDelay(id) : 0,
  };
}
