/**
 * Real-clock time-of-day sky: which tree background layer (morning/midday/
 * afternoon/evening) is showing right now, based on wall-clock time.
 * Independent of js/stageConfig.js, which drives sticky saturation/glow off
 * message count, not time.
 *
 * The festival itself only runs 9:30-16:00, but the display may stay up
 * (or get previewed) outside that window, so `evening` covers 16:00 through
 * end of day and `morning` covers midnight through 9:30 -- a full 24h cycle,
 * not just the display window. morning/midday/afternoon share the same
 * bare-tree composition (see js/branchAnchors.js); evening is a separate
 * sunset painting (Mishima, 2026-09-09), so only its sky/lighting need be
 * consistent with itself, not with the other three.
 */

export const TIME_BUCKETS = [
  { id: "morning", startMinutes: 9 * 60 + 30 },
  { id: "midday", startMinutes: 11 * 60 },
  { id: "afternoon", startMinutes: 14 * 60 },
  { id: "evening", startMinutes: 16 * 60 },
];

const MINUTES_PER_DAY = 24 * 60;

/** Minutes before a boundary where the two neighboring buckets crossfade. */
export const TRANSITION_WINDOW_MINUTES = 30;

function minutesSinceMidnight(date) {
  return date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60;
}

/**
 * @param {Date} date
 * @returns {{ from: string, to: string, progress: number }} `from` and `to`
 *   are TIME_BUCKETS ids (equal when no crossfade is in progress); `progress`
 *   is 0 (fully `from`) to 1 (fully `to`).
 */
export function getTimeBlend(date) {
  const minutes = minutesSinceMidnight(date);
  const firstBucket = TIME_BUCKETS[0];
  const lastBucket = TIME_BUCKETS[TIME_BUCKETS.length - 1];

  if (minutes <= firstBucket.startMinutes) {
    return { from: firstBucket.id, to: firstBucket.id, progress: 0 };
  }

  for (let i = 0; i < TIME_BUCKETS.length; i += 1) {
    const bucket = TIME_BUCKETS[i];
    const nextBucket = TIME_BUCKETS[i + 1];
    const bucketEnd = nextBucket ? nextBucket.startMinutes : MINUTES_PER_DAY;
    if (minutes < bucket.startMinutes || minutes >= bucketEnd) continue;

    const minutesToBoundary = bucketEnd - minutes;
    if (nextBucket && minutesToBoundary <= TRANSITION_WINDOW_MINUTES) {
      const progress = (TRANSITION_WINDOW_MINUTES - minutesToBoundary) / TRANSITION_WINDOW_MINUTES;
      return { from: bucket.id, to: nextBucket.id, progress };
    }
    return { from: bucket.id, to: bucket.id, progress: 0 };
  }

  // Unreachable: the sentinel check above and the loop's own [firstBucket,
  // MINUTES_PER_DAY) range together cover the full 24h clock.
  return { from: lastBucket.id, to: lastBucket.id, progress: 0 };
}
