/**
 * Exhibit mode (?tenji=1 on the student viewer): the page is left open for
 * days on a learning-center PC/TV, so it keeps the screen awake and reloads
 * itself once a day to pick up fixes and shed any long-running cruft.
 * Designed with GPT-5.5 (2026-10-20): reload only after a sheet read has just
 * succeeded, so an offline PC never reloads into a blank screen; Wake Lock is
 * only a helper (released by the browser at will), the OS sleep setting is
 * what really keeps the screen on (see the teachers' setup sheet).
 */
export const RELOAD_AFTER_MS = 24 * 60 * 60 * 1000;
/** A sheet read this recent counts as "online right now". */
export const ONLINE_FRESH_MS = 2 * 60 * 1000;
const RELOAD_CHECK_INTERVAL_MS = 10 * 60 * 1000;

export function isTenjiMode(search) {
  return new URLSearchParams(search).get("tenji") === "1";
}

export function shouldReload({ startedAtMs, nowMs, lastOnlineAtMs }) {
  if (nowMs - startedAtMs < RELOAD_AFTER_MS) {
    return false;
  }
  return lastOnlineAtMs !== null && nowMs - lastOnlineAtMs <= ONLINE_FRESH_MS;
}

/** How often to try again while no wake lock is held (refused, or released while hidden). */
export const WAKE_LOCK_RETRY_MS = 5 * 60 * 1000;

/**
 * Holds a screen wake lock, re-acquiring it whenever the browser lets it go
 * and retrying every WAKE_LOCK_RETRY_MS while none is held, so one refusal
 * doesn't leave a days-long exhibit without it (GPT-5.5 review 2026-10-21).
 */
export async function keepScreenAwake({ wakeLock, doc, setIntervalFn = setInterval }) {
  if (!wakeLock) {
    return;
  }
  let held = false;
  let pending = false;
  async function acquire() {
    if (held || pending || doc.visibilityState !== "visible") {
      return;
    }
    pending = true;
    try {
      const sentinel = await wakeLock.request("screen");
      held = true;
      sentinel.addEventListener("release", () => {
        held = false;
        return acquire();
      });
    } catch (error) {
      // Refused (battery saver, hidden tab...): retried later; the OS sleep setting still applies.
      console.warn("[tenji] wake lock refused:", error?.message ?? error);
    } finally {
      pending = false;
    }
  }
  doc.addEventListener("visibilitychange", acquire);
  setIntervalFn(acquire, WAKE_LOCK_RETRY_MS);
  await acquire();
}

/** Checks every 10 minutes whether the page should reload (see shouldReload). */
export function startDailyReload({ getLastOnlineAtMs, reload, now = Date.now }) {
  const startedAtMs = now();
  return setInterval(() => {
    if (shouldReload({ startedAtMs, nowMs: now(), lastOnlineAtMs: getLastOnlineAtMs() })) {
      reload();
    }
  }, RELOAD_CHECK_INTERVAL_MS);
}
