import { createMessageStore } from "./messageStore.js";
import { createCsvPoller } from "./csvPoller.js";
import { createJsonpRowsLoader } from "./gvizJsonp.js";
import { createIdleReplay } from "./idleReplay.js";
import { createMessageTicker } from "./messageTicker.js";
import { computeFrameScale, computeCountScale, isDenseCount, BASE_STICKY_WIDTH_PX } from "./leafScale.js";
import { getTimeBlend } from "./timeOfDay.js";
import { isTenjiMode, keepScreenAwake, startDailyReload } from "./tenjiMode.js";

const SHEET_URL_STORAGE_KEY = "yushisai-message-tree:sheetUrl";
// The public C/D-only view sheet (勇志祭メッセージツリー_表示用2, filled by
// gas/syncViewSheet.gs), used until something else is saved, so a freshly
// copied festival PC needs no setup. The original 表示用 sheet (1Bh8JW…)
// stopped answering gviz/export on 2026-10-19 and was replaced.
const DEFAULT_SHEET_URL =
  "https://docs.google.com/spreadsheets/d/1o_dQU4QDgNj2KL04wXAheoOi30sv9A3XcAA9WJiXFkw/edit?gid=735394104#gid=735394104";
const CARD_HOLD_MS = 1200;
const CARD_TRAVEL_MS = 900;
const RESIZE_DEBOUNCE_MS = 150;
const STAGE_FLASH_MS = 1400;
const TIME_OF_DAY_UPDATE_MS = 60 * 1000;
// Where the ticker's card/leaf display sits (js/branchAnchors.js CANOPY_POINTS
// tops out at y=66.7%, so this stays clear of the real canopy).
const TICKER_DISPLAY_POINT = { x: 50, y: 76 };
const TICKER_LEAF_HIDDEN_SCALE = 0.45;
const TICKER_LEAF_VISIBLE_SCALE = 1;
// Safety net in case a `transitionend` never fires (reduced-motion, a
// browser quirk, or the settle transition getting interrupted).
const SETTLE_FALLBACK_BUFFER_MS = 300;

function init() {
  const messageStore = createMessageStore();
  // Real (non-replay) messages only, so idle-replay loops through genuine
  // submissions rather than re-replaying its own past replays.
  const realMessages = [];
  // Bumped by resetAllMessages() so any card/settle timer already in flight
  // from before the reset recognizes it's stale and bails instead of
  // reviving a leaf that should have disappeared.
  let renderGeneration = 0;
  const app = document.querySelector(".app");
  const treeFrame = document.querySelector(".tree-frame");
  const stickyLayer = document.querySelector(".sticky-layer");
  const cardLayer = document.querySelector(".card-layer");
  const modal = document.querySelector(".modal");
  const modalMessage = document.querySelector(".modal-message");
  const modalClose = document.querySelector(".modal-close");
  const tickerEl = document.querySelector(".message-ticker");
  const tickerTravelLeaf = document.querySelector(".ticker-travel-leaf");
  const tickerCardEl = document.querySelector(".ticker-card");

  function updateFrameScale() {
    const width = treeFrame.getBoundingClientRect().width;
    document.documentElement.style.setProperty("--frame-scale", String(computeFrameScale(width)));
  }

  let resizeTimer = null;
  function scheduleFrameScaleUpdate() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(updateFrameScale, RESIZE_DEBOUNCE_MS);
  }

  updateFrameScale();
  window.addEventListener("resize", scheduleFrameScaleUpdate);

  function triggerStageFlash() {
    const flash = document.createElement("div");
    flash.className = "stage-flash";
    app.appendChild(flash);
    requestAnimationFrame(() => flash.classList.add("active"));
    setTimeout(() => flash.remove(), STAGE_FLASH_MS);
  }

  let lastAppliedStage = null;
  function applyStage(stageId) {
    app.dataset.stage = String(stageId);
    if (lastAppliedStage !== null && stageId !== lastAppliedStage) {
      triggerStageFlash();
    }
    lastAppliedStage = stageId;
  }

  // `null` means "use the real clock"; a debug override (see the ?debug=1
  // panel below) pins the sky to a chosen time so its look can be checked
  // without waiting for the festival's actual 9:30-16:00 window.
  let debugTimeOverrideMinutes = null;
  const timeLayers = document.querySelectorAll(".time-layer");

  function getTimeOfDayNow() {
    if (debugTimeOverrideMinutes === null) return new Date();
    const overridden = new Date();
    overridden.setHours(Math.floor(debugTimeOverrideMinutes / 60), debugTimeOverrideMinutes % 60, 0, 0);
    return overridden;
  }

  function applyTimeBlend(blend) {
    for (const layer of timeLayers) {
      const id = layer.dataset.timeLayer;
      let opacity = 0;
      if (id === blend.from) opacity += 1 - blend.progress;
      if (id === blend.to) opacity += blend.progress;
      layer.style.opacity = String(opacity);
    }
  }

  function updateTimeOfDay() {
    applyTimeBlend(getTimeBlend(getTimeOfDayNow()));
  }

  updateTimeOfDay();
  setInterval(updateTimeOfDay, TIME_OF_DAY_UPDATE_MS);

  function openModal(message) {
    modalMessage.textContent = message;
    modal.classList.add("open");
  }

  function closeModal() {
    modal.classList.remove("open");
  }

  modalClose.addEventListener("click", closeModal);
  modal.addEventListener("click", (event) => {
    if (event.target === modal) closeModal();
  });

  /**
   * Converts the settled `.card` element in place into its final `.sticky`
   * leaf/flower, instead of removing it and inserting a brand new element.
   * By this point position/color/rotation/scale/shadow/filter already match
   * the target sticky (set at spawn time and transitioned during settling),
   * so the only visible change left is the silhouette itself (organic
   * settling blob -> the precise clip-path outline), which reads as a small
   * detail refinement rather than a jarring swap.
   *
   * The silhouette/color/opacity/sway live on a new `.sticky-visual` child
   * rather than on `.sticky` itself: `.sticky`'s own `transform` already
   * carries position + base rotation + scale, and the wind-sway animation
   * needs its own independent `rotate` without fighting that (GPT-5.5,
   * 2026-09-08 tone/opacity/sway review). The child only needs to exist
   * once a sticky is final -- during the card/settling phase there's no
   * clip-path or sway yet, so it isn't created any earlier.
   */
  function finalizeSticky(card, record) {
    // Drop the inline duration override so the sticky goes back to using
    // --duration-stage for its own later box-shadow/filter transitions.
    card.style.removeProperty("transition-duration");
    card.textContent = "";
    card.classList.remove("card", "settling");
    card.classList.add("sticky");
    card.dataset.id = record.id;
    card.title = record.message;
    card.addEventListener("click", () => openModal(record.message));

    const visual = document.createElement("span");
    visual.className = "sticky-visual";
    visual.dataset.variant = record.variant;
    if (record.swayEnabled) visual.dataset.sway = "true";
    card.appendChild(visual);

    // `.card-layer` is pointer-events:none, so the sticky must move to
    // `.sticky-layer` (same `.tree-frame` coordinate space) to stay clickable.
    stickyLayer.appendChild(card);
  }

  function spawnCard(record) {
    const generation = renderGeneration;
    const card = document.createElement("div");
    card.className = "card";
    card.textContent = record.message;
    card.dataset.kind = record.kind;
    card.dataset.sunlit = String(record.sunlit);
    card.style.setProperty("--leaf-color", record.color);
    card.style.setProperty("--leaf-unit-scale", String(record.leafWidth / BASE_STICKY_WIDTH_PX));
    card.style.setProperty("--leaf-rotation", `${record.rotation}deg`);
    // Consumed by `.sticky-visual` once finalizeSticky() creates it; inherits
    // through as a plain CSS custom property, so no need to set these again there.
    card.style.setProperty("--sticky-opacity", String(record.opacity));
    if (record.swayEnabled) {
      card.style.setProperty("--sway-angle", `${record.swayAngle}deg`);
      card.style.setProperty("--sway-period", `${record.swayPeriod}s`);
      card.style.setProperty("--sway-delay", `${record.swayDelay}s`);
    }
    cardLayer.appendChild(card);

    setTimeout(() => {
      // A reset happened while this card was holding: it's already been
      // removed from the DOM (see resetAllMessages), so don't settle it.
      if (generation !== renderGeneration || !card.isConnected) return;

      card.classList.add("settling");
      card.style.left = `${record.anchor.x}%`;
      card.style.top = `${record.anchor.y}%`;
      const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      // Reduced-motion viewers get the near-instant CSS duration (see
      // --duration-settle in css/style.css); don't override it here.
      if (!reducedMotion) {
        card.style.transitionDuration = `${CARD_TRAVEL_MS}ms`;
      }

      let finalized = false;
      const finalizeOnce = () => {
        if (finalized) return;
        finalized = true;
        card.removeEventListener("transitionend", onTransitionEnd);
        clearTimeout(fallbackTimer);
        if (generation !== renderGeneration || !card.isConnected) return;
        finalizeSticky(card, record);
      };
      const onTransitionEnd = (event) => {
        // Scoped to `transform` (rather than any transitioned property) so
        // a future per-property duration tweak can't trigger an early
        // finalize before position/scale actually finished animating.
        if (event.target === card && event.propertyName === "transform") finalizeOnce();
      };

      card.addEventListener("transitionend", onTransitionEnd);
      const fallbackMs = reducedMotion ? SETTLE_FALLBACK_BUFFER_MS : CARD_TRAVEL_MS + SETTLE_FALLBACK_BUFFER_MS;
      const fallbackTimer = setTimeout(finalizeOnce, fallbackMs);
    }, CARD_HOLD_MS);
  }

  messageStore.onMessageAdded((record) => spawnCard(record));
  /** Shrinks all leaves together and lightens their effects as the tree fills up. */
  function applyDensity(count) {
    document.documentElement.style.setProperty("--leaf-count-scale", String(computeCountScale(count)));
    app.dataset.dense = String(isDenseCount(count));
  }

  messageStore.onChange((stats) => {
    applyStage(stats.stage.id);
    applyDensity(stats.count);
  });
  applyStage(messageStore.getStats().stage.id);
  applyDensity(messageStore.getStats().count);

  const idleReplay = createIdleReplay({
    getMessages: () => realMessages,
    getCurrentCount: () => messageStore.getStats().count,
    onReplay: (record) => messageStore.addMessage(record),
  });

  /**
   * Sets `.ticker-travel-leaf`'s position/visibility, either instantly (the
   * "jump to the start point" half of a travel) or letting the CSS
   * transition animate it (the "move to the target point" half) - same
   * two-step pattern spawnCard() below uses to travel a card from
   * REFERENCE_POINT to its anchor. Driven entirely from JS (not a CSS
   * `[data-phase]` opacity/transform rule) so this two-step can't race a
   * CSS-declared target state.
   */
  function setTravelLeafState(point, { visible, animate }) {
    if (!animate) tickerTravelLeaf.style.transition = "none";
    tickerTravelLeaf.style.left = `${point.x}%`;
    tickerTravelLeaf.style.top = `${point.y}%`;
    tickerTravelLeaf.style.opacity = visible ? "1" : "0";
    const scale = visible ? TICKER_LEAF_VISIBLE_SCALE : TICKER_LEAF_HIDDEN_SCALE;
    tickerTravelLeaf.style.transform = `translate(-50%, -50%) scale(${scale})`;
    if (!animate) {
      void tickerTravelLeaf.offsetHeight; // force reflow before re-enabling the transition
      tickerTravelLeaf.style.transition = "";
    }
  }

  /**
   * Always-on replay ticker, independent of idleReplay's idle-triggered tree
   * regrowth: lets any submitted message be read again, any number of
   * times, oldest first, each popping out from its own real position on the
   * tree and back (Mishima spec, 2026-09-09, refined same day).
   */
  function applyTickerPhase(phase, record) {
    tickerEl.dataset.phase = phase;
    tickerTravelLeaf.dataset.phase = phase;
    if (phase === "idle") {
      // Covers a reset() landing mid-cycle too: hide wherever it currently is
      // rather than leaving a stray leaf visible at a stale position.
      tickerTravelLeaf.style.opacity = "0";
      return;
    }
    tickerTravelLeaf.style.setProperty("--leaf-color", record.color);
    tickerCardEl.textContent = record.message;

    if (phase === "leaf-in") {
      setTravelLeafState(record.anchor, { visible: false, animate: false });
      requestAnimationFrame(() => setTravelLeafState(TICKER_DISPLAY_POINT, { visible: true, animate: true }));
    } else if (phase === "leaf-out") {
      // Already sitting at TICKER_DISPLAY_POINT, visible, from leaf-in/card -
      // just travel it back to where it really lives, fading out en route.
      setTravelLeafState(record.anchor, { visible: false, animate: true });
    }
    // "card" phase: the leaf stays put (visible, at the display point,
    // covered by `.ticker-card` sitting at that same spot) - nothing to do.
  }
  const messageTicker = createMessageTicker({
    getMessages: () => realMessages,
    onPhaseChange: applyTickerPhase,
  });
  messageTicker.start();

  /** Adds a genuine (non-replay) message: sheet row or dev-panel test data. */
  function addRealMessage(raw) {
    const record = messageStore.addMessage(raw);
    if (record) {
      // anchor/color come from the canonical record so the ticker's travel
      // target and leaf color always match the real sticky exactly.
      realMessages.push({
        id: record.id,
        center: record.center,
        message: record.message,
        anchor: record.anchor,
        color: record.color,
      });
      idleReplay.notifyActivity();
    }
    return record;
  }

  function resetAllMessages() {
    renderGeneration += 1;
    messageStore.reset();
    realMessages.length = 0;
    cardLayer.replaceChildren();
    stickyLayer.replaceChildren();
    messageTicker.reset();
  }

  let statusEl = null;
  let lastOnlineAtMs = null;
  // The student viewer (dist-viewer/, scripts/viewerHtml.mjs) has no sheet
  // form or dev panel and always reads the default view sheet.
  const isViewer = document.body.dataset.viewer === "1";
  const getSheetUrl = () =>
    isViewer ? DEFAULT_SHEET_URL : (localStorage.getItem(SHEET_URL_STORAGE_KEY) ?? DEFAULT_SHEET_URL);
  const poller = createCsvPoller({
    getUrl: getSheetUrl,
    loadRows: createJsonpRowsLoader(),
    onNewRecords: (records) => {
      for (const record of records) {
        addRealMessage(record);
      }
    },
    onStatusChange: (status) => {
      if (status.online) {
        lastOnlineAtMs = Date.now();
      }
      if (statusEl) {
        statusEl.dataset.online = String(status.online);
        statusEl.textContent = status.online ? "オンライン" : "オフライン(再試行中)";
      }
    },
  });

  poller.start();
  if (isViewer && isTenjiMode(window.location.search)) {
    // Learning-center exhibit display (js/tenjiMode.js).
    document.body.dataset.tenji = "1";
    document.querySelector(".tenji-panel").hidden = false;
    keepScreenAwake({ wakeLock: navigator.wakeLock, doc: document });
    startDailyReload({ getLastOnlineAtMs: () => lastOnlineAtMs, reload: () => window.location.reload() });
  }
  if (isViewer) return;

  statusEl = document.querySelector(".sheet-status");
  const urlInput = document.querySelector(".sheet-url-input");
  const saveButton = document.querySelector(".sheet-url-save");
  urlInput.value = getSheetUrl();

  saveButton.addEventListener("click", () => {
    const url = urlInput.value.trim();
    poller.stop();
    if (url) {
      localStorage.setItem(SHEET_URL_STORAGE_KEY, url);
    } else {
      // Saving an empty field means "back to the default view sheet".
      localStorage.removeItem(SHEET_URL_STORAGE_KEY);
      urlInput.value = DEFAULT_SHEET_URL;
    }
    poller.start();
  });

  // Dev-only manual message-count control, shown only with ?debug=1 so
  // festival attendees never see it on the live display.
  const devPanel = document.querySelector(".dev-panel");
  if (new URLSearchParams(window.location.search).get("debug") === "1") {
    devPanel.hidden = false;
  }

  // Cycled through so ?debug=1 test data exercises every venue's leaf color,
  // not just the fallback hash-based one an unrecognized center would get.
  const DEV_CENTERS = ["福岡", "熊本", "宮崎", "大分", "千葉"];

  function setDevMessageCount(targetCount) {
    if (targetCount < messageStore.getStats().count) {
      resetAllMessages();
    }
    for (let i = messageStore.getStats().count; i < targetCount; i += 1) {
      addRealMessage({ id: `dev_${i}`, center: DEV_CENTERS[i % DEV_CENTERS.length], message: `開発用テストメッセージ ${i + 1}` });
    }
  }

  document.querySelector(".dev-count-apply").addEventListener("click", () => {
    const target = Math.floor(Number(document.querySelector(".dev-count-input").value));
    if (Number.isFinite(target) && target >= 0) {
      setDevMessageCount(target);
    }
  });

  document.querySelector(".dev-count-reset").addEventListener("click", resetAllMessages);

  document.querySelector(".dev-time-apply").addEventListener("click", () => {
    const [hours, minutes] = document.querySelector(".dev-time-input").value.split(":").map(Number);
    if (Number.isFinite(hours) && Number.isFinite(minutes)) {
      debugTimeOverrideMinutes = hours * 60 + minutes;
      updateTimeOfDay();
    }
  });

  document.querySelector(".dev-time-reset").addEventListener("click", () => {
    debugTimeOverrideMinutes = null;
    updateTimeOfDay();
  });

  window.__debug = {
    messageStore,
    poller,
    applyStage,
    spawnCard,
    idleReplay,
    messageTicker,
    realMessages,
    setDevMessageCount,
    updateTimeOfDay,
    setDebugTime: (hours, minutes) => {
      debugTimeOverrideMinutes = hours * 60 + minutes;
      updateTimeOfDay();
    },
  };
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", init);
} else {
  init();
}
