/**
 * Growth stages: 6 message-count milestones that drive ambient stage effects
 * (sky gradient warmth, sticky saturation/glow, a milestone flash — see
 * css/style.css `.app[data-stage]` rules and js/main.js `applyStage`).
 * The background art itself no longer changes per stage: it stays the
 * bare stage-1 tree throughout, and messages (rendered as leaf/flower
 * stickies) are what visually fill it in toward a stage-6-like canopy.
 * Thresholds are a starting point tuned for a multi-hundred-message event;
 * adjust `min` values freely, they carry no other meaning.
 */
export const STAGES = [
  { id: 1, min: 0 },
  { id: 2, min: 10 },
  { id: 3, min: 25 },
  { id: 4, min: 45 },
  { id: 5, min: 70 },
  { id: 6, min: 100 },
];

/** Transition duration for stage-change effects (sky/glow crossfade, flash). */
export const STAGE_TRANSITION_MS = 800;

export function getStageForCount(count) {
  let current = STAGES[0];
  for (const stage of STAGES) {
    if (count >= stage.min) {
      current = stage;
    }
  }
  return current;
}
