/**
 * Minimal RFC4180-ish CSV parser (quoted fields, "" escapes, embedded commas
 * and newlines) for Google Sheets' published CSV export. No external
 * dependency, since this project ships as build-free vanilla JS.
 */
export function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  let i = 0;

  function endField() {
    row.push(field);
    field = "";
  }

  function endRow() {
    endField();
    rows.push(row);
    row = [];
  }

  while (i < text.length) {
    const char = text[i];
    if (inQuotes) {
      if (char === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        continue;
      }
      field += char;
      i += 1;
      continue;
    }

    if (char === '"') {
      inQuotes = true;
      i += 1;
      continue;
    }
    if (char === ",") {
      endField();
      i += 1;
      continue;
    }
    if (char === "\r") {
      i += 1;
      continue;
    }
    if (char === "\n") {
      endRow();
      i += 1;
      continue;
    }
    field += char;
    i += 1;
  }

  if (field !== "" || row.length > 0) {
    endRow();
  }

  return rows.filter((r) => !(r.length === 1 && r[0].trim() === ""));
}

/**
 * Maps raw CSV rows (header + data) to {id, center, message} records.
 * The CSV export is restricted to columns C (学習センター) and D (message)
 * via js/csvPoller.js's `toCsvUrl()` (`range=C:D`) — column A (timestamp)
 * and B (email, PII) never reach this parser at all, so cols[0] is always
 * center and cols[1] is always message.
 *
 * `id` is derived from the content (plus how many identical posts came
 * before it), not the row position: deleting a row on the day (moderation)
 * shifts every later row up, and a position-based id would then make the
 * app treat brand-new posts as already seen.
 */
export function csvRowsToRecords(rows) {
  const [, ...dataRows] = rows;
  if (!dataRows) return [];

  const records = [];
  const occurrences = new Map();
  for (const cols of dataRows) {
    const message = (cols[1] ?? "").trim();
    if (!message) continue;
    const center = (cols[0] ?? "").trim();
    const key = `${center}|${message}`;
    const occurrence = occurrences.get(key) ?? 0;
    occurrences.set(key, occurrence + 1);
    records.push({ id: `msg:${key}#${occurrence}`, center, message });
  }
  return records;
}
