// Matches the leaf's travel transition in css/style.css (`.ticker-travel-leaf`,
// 1s) - the leaf physically moves between the message's real anchor on the
// tree and the fixed display point (Mishima, 2026-09-09 follow-up: "葉っぱが
// ついている場所から飛び出てきてまたそこに戻っていく"), so JS must wait for
// that full travel before advancing the phase again.
const DEFAULT_LEAF_TRAVEL_MS = 1050;
const DEFAULT_CARD_HOLD_MIN_MS = 4500;
const DEFAULT_CARD_HOLD_MAX_MS = 10000;
const DEFAULT_CARD_HOLD_PER_CHAR_MS = 120;
const DEFAULT_GAP_MS = 1500;

/** How long a message's card stays up: longer messages get more read time, within sane bounds. */
function defaultCardHoldMs(record) {
  const scaled = record.message.length * DEFAULT_CARD_HOLD_PER_CHAR_MS;
  return Math.max(DEFAULT_CARD_HOLD_MIN_MS, Math.min(DEFAULT_CARD_HOLD_MAX_MS, scaled));
}

/**
 * Runs a bottom-of-screen "replay ticker" so every submitted message can be
 * read again, any number of times, independent of js/idleReplay.js (which
 * exists to keep the *tree* visibly growing during quiet stretches, not to
 * make past messages re-readable). Cycles oldest-to-newest through
 * `getMessages()` forever, one message at a time, each in a
 * leaf -> card -> leaf cycle (Mishima spec, 2026-09-09, refined 2026-09-09):
 * the leaf pops out from that message's real position on the tree and
 * travels to a fixed display point, crossfades to the full message card,
 * holds (longer for a longer message), then the leaf travels back to its
 * real tree position, then a short gap before the next message.
 *
 * DOM-agnostic like idleReplay.js: `onPhaseChange(phase, record)` is the only
 * side effect, so the caller owns rendering and this stays testable with
 * `t.mock.timers`. `phase` is one of "leaf-in" | "card" | "leaf-out" | "idle"
 * ("idle" also carries a null record: nothing to show, between messages or
 * when there are no messages yet).
 */
export function createMessageTicker({
  getMessages,
  onPhaseChange,
  leafTravelMs = DEFAULT_LEAF_TRAVEL_MS,
  gapMs = DEFAULT_GAP_MS,
  cardHoldMs = defaultCardHoldMs,
}) {
  let cursor = 0;
  let timer = null;
  let running = false;

  function scheduleNext(delayMs, fn) {
    timer = setTimeout(fn, delayMs);
  }

  function goIdleThenRetry() {
    onPhaseChange("idle", null);
    scheduleNext(gapMs, runCycle);
  }

  function runCycle() {
    const messages = getMessages();
    if (messages.length === 0) {
      goIdleThenRetry();
      return;
    }
    const record = messages[cursor % messages.length];
    cursor += 1;

    onPhaseChange("leaf-in", record);
    scheduleNext(leafTravelMs, () => {
      onPhaseChange("card", record);
      scheduleNext(cardHoldMs(record), () => {
        onPhaseChange("leaf-out", record);
        scheduleNext(leafTravelMs, goIdleThenRetry);
      });
    });
  }

  function start() {
    if (running) return;
    running = true;
    runCycle();
  }

  function stop() {
    running = false;
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  /** Back to the oldest message and idle, e.g. after resetAllMessages(). */
  function reset() {
    cursor = 0;
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    if (running) {
      goIdleThenRetry();
    }
  }

  return { start, stop, reset };
}
