const SHEET_ID_PATTERN = /\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/;
const GID_PATTERN = /[?#&]gid=([0-9]+)/;
const DEFAULT_TIMEOUT_MS = 15000;
const CALLBACK_PREFIX = "__yushisaiTreeGviz_";

/**
 * Loads the C/D view sheet via gviz JSONP (`<script>` injection) instead of
 * fetch, because the festival PC opens index.html straight from disk
 * (file://, origin "null") and gviz only returns Access-Control-Allow-Origin
 * for real http(s) origins — a fetch from file:// is always CORS-blocked.
 *
 * JSONP *executes* whatever the url returns, so the url is never derived
 * from the user's input string: only the sheet id and gid are pulled out
 * and the url is rebuilt on docs.google.com, pinned to range=C:D (never A
 * timestamp / B email). headers=0 makes gviz return row 1 (the header row)
 * as data, matching the csv export that csvRowsToRecords expects.
 */
export function toGvizJsonpUrl(sheetInput, callbackName) {
  const match = SHEET_ID_PATTERN.exec(sheetInput ?? "");
  if (!match) return null;
  const gidMatch = GID_PATTERN.exec(sheetInput);
  const gid = gidMatch ? gidMatch[1] : "0";
  return (
    `https://docs.google.com/spreadsheets/d/${match[1]}/gviz/tq` +
    `?tqx=out:json;responseHandler:${callbackName}&headers=0&gid=${gid}&range=C:D`
  );
}

/** gviz table -> string[][] (same shape parseCsv returns). */
export function gvizTableToRows(response) {
  if (response?.status !== "ok" || !response.table) {
    throw new Error(`gviz error: ${response?.status ?? "no response"}`);
  }
  return response.table.rows.map((row) =>
    (row.c ?? []).map((cell) => (cell?.v == null ? "" : String(cell.v))),
  );
}

/**
 * Returns `loadRows(sheetInput) -> Promise<string[][]>` for createCsvPoller.
 * Every outcome (callback, script error, timeout) runs the same one-shot
 * cleanup, so no <script> or window callback is left behind.
 */
export function createJsonpRowsLoader({
  doc = document,
  win = window,
  timeoutMs = DEFAULT_TIMEOUT_MS,
} = {}) {
  let sequence = 0;

  return function loadRows(sheetInput) {
    sequence += 1;
    const callbackName = `${CALLBACK_PREFIX}${Date.now()}_${sequence}`;
    const url = toGvizJsonpUrl(sheetInput, callbackName);
    if (!url) return Promise.reject(new Error("no spreadsheet id in sheet url"));

    return new Promise((resolve, reject) => {
      const script = doc.createElement("script");
      let settled = false;

      function finish(error, rows) {
        if (settled) return;
        settled = true;
        clearTimeout(timeoutId);
        delete win[callbackName];
        script.remove();
        if (error) reject(error);
        else resolve(rows);
      }

      const timeoutId = setTimeout(() => finish(new Error("gviz jsonp timeout")), timeoutMs);
      win[callbackName] = (response) => {
        try {
          finish(null, gvizTableToRows(response));
        } catch (error) {
          finish(error);
        }
      };
      script.onerror = () => finish(new Error("gviz jsonp script failed to load"));
      script.src = url;
      doc.head.appendChild(script);
    });
  };
}
