import { getAllAnchors, REFERENCE_POINT, isOnTrunk } from "./branchAnchors.js";
import { sortAnchorsByDistance, computeAnchorAssignment, computeStickyOffset } from "./anchorPlacement.js";
import { getStageForCount } from "./stageConfig.js";
import { NATIVE_FRAME_WIDTH, NATIVE_FRAME_HEIGHT } from "./leafScale.js";
import { resolveStickyVisual, getStickyScatter } from "./stickyVisuals.js";

/** How many alternative scatter spots to try before falling back to the anchor itself. */
const MAX_SCATTER_ATTEMPTS = 8;

/** Converts a jitter offset in native artwork px to `.tree-frame` percent. */
function jitterToPercent({ dxPx, dyPx }) {
  return { dx: (dxPx / NATIVE_FRAME_WIDTH) * 100, dy: (dyPx / NATIVE_FRAME_HEIGHT) * 100 };
}

function resolvePlacement(raw, anchorPoint, offset) {
  // The overflow scatter can move a repeat occupant up to SCATTER_RADIUS_PX
  // from its anchor, so resolve sunlit-side placement against where it
  // actually lands, not the shared anchor point every occupant there starts from.
  const settledAnchor = { x: anchorPoint.x + offset.dx, y: anchorPoint.y + offset.dy };
  const visual = resolveStickyVisual(raw.id, settledAnchor, raw.center);
  return { settledAnchor, jitter: jitterToPercent(visual.jitter), visual };
}

/**
 * Picks a scatter spot whose final (jittered) position is off the trunk,
 * retrying with fresh spots; if none clears it, settles exactly on the
 * anchor, which is verified to sit on a branch (js/branchAnchors.js).
 */
function placeOffTrunk(raw, anchorPoint, occupantIndex) {
  for (let attempt = 0; attempt < MAX_SCATTER_ATTEMPTS; attempt += 1) {
    const placement = resolvePlacement(raw, anchorPoint, computeStickyOffset(occupantIndex, getStickyScatter(raw.id, attempt)));
    const { settledAnchor, jitter } = placement;
    if (!isOnTrunk({ x: settledAnchor.x + jitter.dx, y: settledAnchor.y + jitter.dy })) {
      return placement;
    }
  }
  const placement = resolvePlacement(raw, anchorPoint, { dx: 0, dy: 0 });
  return { ...placement, jitter: { dx: 0, dy: 0 } };
}

export function createMessageStore() {
  const anchors = getAllAnchors();
  const sortedAnchorIndices = sortAnchorsByDistance(anchors, REFERENCE_POINT);

  let messages = [];
  let seenIds = new Set();
  const changeListeners = new Set();
  const addListeners = new Set();

  function getStats() {
    const count = messages.length;
    return { count, stage: getStageForCount(count) };
  }

  function notifyChange() {
    const snapshot = getStats();
    for (const listener of changeListeners) {
      listener(snapshot);
    }
  }

  function addMessage(raw) {
    if (seenIds.has(raw.id)) {
      return null;
    }

    const orderIndex = messages.length;
    const { anchorIndex, occupantIndex } = computeAnchorAssignment(orderIndex, sortedAnchorIndices);
    const { settledAnchor, jitter, visual } = placeOffTrunk(raw, anchors[anchorIndex], occupantIndex);

    const record = {
      id: raw.id,
      center: raw.center,
      message: raw.message,
      anchor: {
        x: settledAnchor.x + jitter.dx,
        y: settledAnchor.y + jitter.dy,
      },
      kind: visual.kind,
      variant: visual.variant,
      color: visual.color,
      opacity: visual.opacity,
      sunlit: visual.sunlit,
      leafWidth: visual.width,
      rotation: visual.rotation,
      swayEnabled: visual.swayEnabled,
      swayAngle: visual.swayAngle,
      swayPeriod: visual.swayPeriod,
      swayDelay: visual.swayDelay,
    };

    seenIds.add(raw.id);
    messages.push(record);
    for (const listener of addListeners) {
      listener(record);
    }
    notifyChange();
    return record;
  }

  function reset() {
    messages = [];
    seenIds = new Set();
    notifyChange();
  }

  function onChange(listener) {
    changeListeners.add(listener);
    return () => changeListeners.delete(listener);
  }

  function onMessageAdded(listener) {
    addListeners.add(listener);
    return () => addListeners.delete(listener);
  }

  return {
    addMessage,
    reset,
    onChange,
    onMessageAdded,
    getStats,
    getMessages: () => messages.slice(),
  };
}
